function art(i,group,x){
  const type=group==='current'?'current':group==='global'?'global-classic':'classic-german';
  return {category:'作品/展覽',status:'官方來源',updated:date,id:`${type}-${date}-${String(i).padStart(2,'0')}`,
    dedupeKey:`art-${date}-${group}-${slug(x.title)}-${slug(x.artist)}`,name:`${String(i).padStart(2,'0')}｜${x.artist}｜${x.title}`,
    tier:group==='current'?'動態情報層':'經典檔案庫',region:group==='global'?'西方':'西方',country:x.country,cityKeywords:x.cityKeywords,media:x.media,
    works:`${x.title}｜${x.year}`,comment:x.comment,website:x.source,workPage:x.source,photo:x.image,
    artistStatement:x.comment,artistStatementSource:x.source,classicTitle:`${x.title}｜${x.year}`,classicImage:x.image,classicDesc:x.desc,relatedByCity:[]};
}

